from math import gcd
class Solution:
    def countSelfDivisiblePermutations(self, n):
        size = 1 << n
        dp = [0] * size
        dp[0] = 1
        for mask in range(size):
            if not dp[mask]:
                continue
            i = bin(mask).count('1') + 1
            for v in range(1, n + 1):
                if not mask >> (v - 1) & 1 and gcd(v, i) == 1:
                    dp[mask | 1 << (v - 1)] += dp[mask]
        return dp[-1]

