from math import gcd
from functools import lru_cache
class Solution:
    def countSelfDivisiblePermutations(self, n):
        @lru_cache(maxsize=None)
        def go(mask):
            i = bin(mask).count('1') + 1
            if i > n:
                return 1
            total = 0
            for v in range(1, n + 1):
                if not mask >> (v - 1) & 1 and gcd(v, i) == 1:
                    total += go(mask | 1 << (v - 1))
            return total
        return go(0)

