class Solution {
    private int n;
    private long[] memo;
    public int countSelfDivisiblePermutations(int n) {
        this.n = n;
        this.memo = new long[1 << n];
        Arrays.fill(memo, -1L);
        return (int) go(0);
    }
    private long go(int mask) {
        if (memo[mask] != -1) return memo[mask];
        int i = Integer.bitCount(mask) + 1;
        if (i > n) return memo[mask] = 1;
        long total = 0;
        for (int v = 1; v <= n; v++)
            if ((mask >> (v - 1) & 1) == 0 && gcd(v, i) == 1)
                total += go(mask | 1 << (v - 1));
        return memo[mask] = total;
    }
    private int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }
}

