    function go(mask) {
        if (memo[mask] !== -1) return memo[mask];
        const i = bc(mask) + 1;
        if (i > n) return (memo[mask] = 1);
        let total = 0;
        for (let v = 1; v <= n; v++)
            if (!((mask >> (v - 1)) & 1) && gcd(v, i) === 1)
                total += go(mask | (1 << (v - 1)));
        return (memo[mask] = total);
    }
    return go(0);
};
